<?php
require 'config.php';if(!empty($_SESSION['user_id']))redirect('dashboard.php');$error='';$name='';$email='';$timezone='Europe/Copenhagen';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$name=input_string('full_name');$email=strtolower(input_string('email'));$password=is_string($_POST['password']??null)?$_POST['password']:'';$timezone=input_string('timezone');
 if($name===''||mb_strlen($name)>100)$error='Enter your name using 1–100 characters.';
 elseif(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$error='Enter a valid email address.';
 elseif(strlen($password)<8||strlen($password)>72)$error='Use a password between 8 and 72 bytes (characters for basic Latin text).';
 elseif(!in_array($timezone,DateTimeZone::listIdentifiers(),true))$error='Choose a valid time zone.';
 // Store a one-way password hash, never the plain password; login checks it with password_verify().
 else try{$pdo->prepare('INSERT INTO users(full_name,email,password_hash,timezone) VALUES(?,?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$timezone]);flash('success','Your account is ready. Sign in to create your first task.');redirect('login.php');}catch(PDOException $ex){$error=$ex->getCode()==='23000'?'An account already uses this email. Try signing in.':'We could not create your account. Please try again.';}
}
$pageTitle='Create account';include 'includes/header.php';?>
